    return { text: `The class has $${n * c + d}. A ball costs $${d}. Cones cost $${c} each. How many cones can we buy after buying the ball?`, visual: "🧾", answer: n,
      hints: ["Pay for the ball first.", `Subtract $${d} from the budget, then divide what is left by $${c}.`, "Example: $40 with a $10 ball and $5 cones: 30 ÷ 5 = 6 cones. Now do yours."] };
